(5894,'frFR','Monty, que je m\'appelle, et j\'ai des rats à la pelle.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(5894,'koKR','내 이름은 몬티. 쥐들은 내 사냥감이지.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(5894,'ruRU','Монти я зовусь, с крысами вожусь!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(5894,'zhCN','我名叫蒙提，老鼠是我的玩物。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
