(13030,'esES','¡Saludos, $c!$b$bEspero que no te moleste el trabajo duro. Nos vendría bien un poco de ayuda.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(13030,'esMX','¡Saludos, $c!$b$bEspero que no te moleste el trabajo duro. Nos vendría bien un poco de ayuda.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
