(16280,'frFR','Faites vos préparatifs, $n, mais faites-les vite !',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(16280,'koKR','준비 단단히 하십시오, $n 님. 하지만 빨리하셔야 합니다!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(16280,'ruRU','Закончи приготовления, $n, да побыстрее!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
