(22493,'esMX','Mis seh\'pientes, colega. ¡Se llevaron mis seh\'pientes!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(22493,'frFR','Mes serpents, mec. Z’ont pris mes serpents !',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
